    shape = observation.get('shape', [1, 1])
    height, width = shape
    player = observation.get('player', {})
    allies = observation.get('allies', [])
    enemies = observation.get('enemies', [])
    resources = observation.get('resources', [])
    territory = observation.get('territory', [])
    agent_pos = player.get('pos', [0, 0])

    def is_valid(pos):
        x, y = pos
        return 0 <= x < width and 0 <= y < height

    def neighbors(pos):
        x, y = pos
        for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
            new_pos = [x + dx, y + dy]
            if is_valid(new_pos):
                yield new_pos

    def closest(targets):
        min_dist = float('inf')
        target_pos = None
        for t in targets:
            dx_t = t[0] - agent_pos[0]
            dy_t = t[1] - agent_pos[1]
            dist = abs(dx_t) + abs(dy_t)
            if dist < min_dist:
                min_dist = dist
                target_pos = t
        return target_pos

    target_resource = closest(resources) if resources else None
    target_enemy = closest(enemies) if enemies else None
    # Prioritize resource collection, then pursuit
    target = None
    if target_resource:
        target = target_resource
    elif target_enemy:
        target = target_enemy
    else:
        target = agent_pos

    delta_x = target[0] - agent_pos[0]
    delta_y = target[1] - agent_pos[1]

    # Decide movement: move along the axis with larger distance
    if abs(delta_x) >= abs(delta_y) and delta_x != 0:
        dx = 1 if delta_x > 0 else -1
        dy = 0
    elif delta_y != 0:
        dx = 0
        dy = 1 if delta_y > 0 else -1
    else:
        dx = 0
        dy = 0

    new_pos = [agent_pos[0] + dx, agent_pos[1] + dy]
    if not is_valid(new_pos):
        alt_moves = []
        if abs(delta_x) >= abs(delta_y) and delta_y != 0:
            alt_moves.append((0, 1 if delta_y > 0 else -1))
        if delta_x != 0:
            alt_moves.append((1 if delta_x > 0 else -1, 0))
        for alt_dx, alt_dy in alt_moves:
            alt_pos = [agent_pos[0] + alt_dx, agent_pos[1] + alt_dy]
            if is_valid(alt_pos):
                dx, dy = alt_dx, alt_dy
                break
        else:
            dx, dy = 0, 0
    return [dx, dy]

